using System.ComponentModel;
using System.Net.Http.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public static class FetchDataTool
{
    [McpServerTool, Description("Fetches data from an external API endpoint.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        ILogger<McpServer.Tools.Marker> logger,
        [Description("The API path to query (e.g. \"/users/1\").")] string path,
        CancellationToken cancellationToken = default)
    {
        var client = httpClientFactory.CreateClient("ExternalApi");

        logger.LogInformation("Calling external API: {Path}", path);

        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);

        logger.LogInformation("Received {Length} chars from API", content.Length);
        return content;
    }
}

// Marker type for ILogger<T> generic parameter.
internal sealed class Marker;

